// NEET UG Biology: Cell, the unit of life (NCERT Class 11, Chapter 8). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `cl-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];

// single-answer mcq; the right option is placed at a cycling position
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}

// ---------------------------------------------------------------- Level 1
mc(1, 'cell theory', 'Who discovered the nucleus in the cell?', 'Robert Brown', ['Matthias Schleiden', 'Rudolf Virchow', 'Theodor Schwann'], 'Robert Brown discovered the nucleus in 1831. Schleiden and Schwann proposed the cell theory, and Virchow added that new cells arise from pre-existing cells.');
mc(1, 'cell theory', 'The statement "Omnis cellula-e cellula" (every cell arises from a pre-existing cell) was made by', 'Rudolf Virchow', ['Matthias Schleiden', 'Theodor Schwann', 'Robert Brown'], 'Virchow (1855) completed the cell theory by explaining that cells divide and new cells come from existing cells. Schleiden and Schwann had said only that plants and animals are made of cells.');
mc(1, 'mitochondria', 'Which cell organelle is called the "powerhouse of the cell"?', 'Mitochondrion', ['Golgi apparatus', 'Lysosome', 'Ribosome'], 'Mitochondria are the sites of aerobic respiration and make most of the cell\'s ATP, so they are called powerhouses.');
mc(1, 'ribosomes', 'The ribosomes of a bacterium are of which type?', '70S', ['80S', '60S', '40S'], 'Prokaryotic ribosomes are 70S (50S + 30S subunits). 80S (60S + 40S) is the eukaryotic cytoplasmic ribosome.');
mc(1, 'ribosomes', 'The organelle on which proteins are made is the', 'ribosome', ['lysosome', 'Golgi body', 'vacuole'], 'Ribosomes read mRNA and join amino acids into proteins. Golgi packages and modifies; lysosomes digest; vacuoles store.');
mc(1, 'cell wall', 'The main chemical component of the plant cell wall is', 'cellulose', ['chitin', 'peptidoglycan only', 'starch'], 'Plant cell walls are built mostly of cellulose, with hemicellulose, pectins and proteins. Chitin is the fungal wall component.');
mc(1, 'plant vs animal cell', 'Which of the following is found in a plant cell but NOT in an animal cell?', 'Cell wall', ['Plasma membrane', 'Ribosomes', 'Nucleus'], 'Animal cells have only a plasma membrane. A cell wall (outside the plasma membrane), plastids and a large central vacuole are characteristic of plant cells.');
mc(1, 'cell size', 'The smallest known cell is that of', 'Mycoplasma', ['Escherichia coli', 'human red blood cell', 'Amoeba'], 'Mycoplasma (PPLO) is only about 0.3 µm long. Bacteria are usually 3 to 5 µm and a human RBC is about 7 µm across.');
mc(1, 'membrane', 'The fluid mosaic model of the plasma membrane was proposed by', 'Singer and Nicolson', ['Schleiden and Schwann', 'Watson and Crick', 'Hershey and Chase'], 'Singer and Nicolson proposed the fluid mosaic model in 1972: proteins float like a mosaic in a fluid lipid bilayer.');
mc(1, 'lysosomes', 'Lysosomes are rich in', 'hydrolytic enzymes', ['respiratory enzymes', 'photosynthetic pigments', 'DNA polymerases only'], 'Lysosomes hold lipases, proteases, carbohydrases and nucleases (hydrolases) that work best at acidic pH, so they digest all major biomolecules.');
mc(1, 'plastids', 'The green coloured plastid is the', 'chloroplast', ['chromoplast', 'leucoplast', 'amyloplast'], 'Chloroplasts contain chlorophyll. Chromoplasts are yellow, orange or red; leucoplasts are colourless.');
mc(1, 'plastids', 'A stack of thylakoids in a chloroplast is called a', 'granum', ['crista', 'stroma', 'cisterna'], 'Thylakoids are stacked like a pile of coins to form a granum (plural grana). Cristae belong to mitochondria; cisternae to the Golgi and ER.');
mc(1, 'cilia and flagella', 'The arrangement of microtubules in the axoneme of a eukaryotic cilium is', '9 + 2', ['9 + 0', '9 + 1', '3 + 2'], 'Nine peripheral doublets surround two central single microtubules: the 9+2 pattern. 9+0 (triplets) is seen in centrioles and basal bodies.');
mc(1, 'Golgi', 'Packaging and secretion of materials from the cell is the main job of the', 'Golgi apparatus', ['mitochondrion', 'nucleolus', 'peroxisome only'], 'The Golgi complex modifies, sorts and packages materials, then sends them to targets inside or outside the cell.');

// ---------------------------------------------------------------- Level 2
mc(2, 'prokaryotic cell', 'Which of these is NOT a part of the bacterial flagellum?', 'Axoneme', ['Filament', 'Hook', 'Basal body'], 'A bacterial flagellum has three parts: filament, hook and basal body. The axoneme with 9+2 microtubules is a eukaryotic structure.');
mc(2, 'prokaryotic cell', 'Mesosomes in a bacterial cell are', 'infoldings of the plasma membrane', ['membrane-bound sacs holding DNA', 'storage granules of glycogen', 'proteinaceous appendages used for attachment'], 'Mesosomes are vesicles, tubules or lamellae formed by infolding of the plasma membrane. They help in cell wall formation, DNA replication and distribution, and respiration, and they raise the enzyme content and surface area.', 'Mesosomes are not membrane-bound organelles in the eukaryotic sense; they are part of the plasma membrane itself.');
mc(2, 'prokaryotic cell', 'Small, circular, extra-chromosomal DNA of bacteria that often gives antibiotic resistance is called', 'plasmid', ['nucleoid', 'episome-free genome', 'mesosome'], 'Plasmids are small circular DNA molecules outside the genomic DNA. They give unique phenotypes such as antibiotic resistance and are used to monitor transformation. The nucleoid is the region holding the main chromosome.');
mc(2, 'prokaryotic cell', 'In a bacterium the glycocalyx is called a capsule when it is', 'thick and tough', ['loose and soft', 'made only of lipid', 'inside the plasma membrane'], 'A loose sheath is a slime layer; a thick and tough glycocalyx is a capsule.');
mc(2, 'prokaryotic cell', 'Bacteria that retain the Gram stain are called', 'Gram positive', ['Gram negative', 'acid fast only', 'cyanobacteria'], 'Gram-positive bacteria take up the stain; Gram-negative ones do not. The difference lies in the chemical nature of the cell envelope.');
mc(2, 'membrane', 'The lipids of the plasma membrane are arranged so that', 'polar heads face outward and non-polar tails face inward', ['non-polar heads face outward and polar tails face inward', 'all heads and tails mix evenly', 'only proteins face the water'], 'Phospholipids have a hydrophilic polar head and hydrophobic tails. In water the heads point to the aqueous sides and the tails hide in the middle of the bilayer.');
mc(2, 'membrane', 'Which of the following needs ATP?', 'Active transport', ['Simple diffusion', 'Facilitated diffusion', 'Osmosis'], 'Active transport moves molecules against a concentration gradient and needs energy (ATP). Diffusion, facilitated diffusion and osmosis are passive and go down a gradient.');
mc(2, 'membrane', 'In the human erythrocyte membrane the approximate percentages of protein and lipid are', '52 and 40', ['40 and 52', '10 and 90', '70 and 5'], 'NCERT gives about 52 per cent protein and 40 per cent lipid for the RBC membrane. The rest is mainly carbohydrate.', 'Do not reverse the two numbers; protein is the larger share in the RBC membrane.');
mc(2, 'vacuole', 'The membrane that surrounds a plant vacuole is the', 'tonoplast', ['plasmalemma', 'cristae', 'middle lamella'], 'The single membrane around a vacuole is the tonoplast; it helps move ions and other materials into the vacuole against a concentration gradient.');
mc(2, 'plastids', 'Starch is stored in colourless plastids called', 'amyloplasts', ['elaioplasts', 'aleuroplasts', 'chromoplasts'], 'Amyloplasts store starch, elaioplasts store oils and fats, aleuroplasts store proteins. Chromoplasts hold coloured carotenoids.');
mc(2, 'mitochondria', 'The infoldings of the inner mitochondrial membrane are called', 'cristae', ['grana', 'cisternae', 'thylakoids'], 'Cristae project into the matrix and increase the surface area for ATP-making enzymes.');
mc(2, 'Golgi', 'The face of the Golgi complex that receives vesicles from the ER is the', 'cis (forming) face', ['trans (maturing) face', 'lateral face', 'luminal face'], 'The Golgi has a cis (forming) face near the ER and a trans (maturing) face towards the plasma membrane; the two faces are different but connected.');
mc(2, 'ER', 'The major site of lipid synthesis in the cell is the', 'smooth endoplasmic reticulum', ['rough endoplasmic reticulum', 'Golgi complex', 'lysosome'], 'SER makes lipids; in animal cells it also makes steroidal hormones. RER with attached ribosomes is active in protein synthesis and secretion.');
mc(2, 'centriole', 'The arrangement of microtubules in a centriole is', '9 triplets with no central tubules', ['9 doublets with 2 central tubules', '9 singlets with 1 central tubule', '2 triplets with 9 central tubules'], 'A centriole is like a cartwheel: nine evenly spaced peripheral fibrils, each a triplet of tubulin, joined to a central hub by radial spokes. This is the 9+0 pattern.');
mc(2, 'nucleus', 'Ribosomal RNA is actively synthesised in the', 'nucleolus', ['nuclear pore', 'perinuclear space', 'Golgi body'], 'The nucleolus is not membrane bound and is the site of rRNA synthesis. Cells making lots of protein have larger and more nucleoli.');
mc(2, 'nucleus', 'The proteins that are combined with DNA in chromatin are mainly', 'basic histones', ['acidic keratins', 'enzymes of respiration', 'tubulins'], 'Chromatin has DNA, basic proteins called histones, some non-histone proteins and RNA.');
mc(2, 'chromosomes', 'A chromosome with its centromere in the middle, so the two arms are equal, is', 'metacentric', ['sub-metacentric', 'acrocentric', 'telocentric'], 'Metacentric: middle centromere, equal arms. Sub-metacentric: slightly off the middle. Acrocentric: close to one end. Telocentric: terminal.');
mc(2, 'nucleus', 'Nuclear pores allow passage of', 'RNA and protein molecules in both directions', ['only DNA out of the nucleus', 'only water into the nucleus', 'nothing larger than ions'], 'Pores in the double nuclear envelope let RNA and proteins move between nucleus and cytoplasm in both directions.');
mc(2, 'cell wall', 'The layer that cements neighbouring plant cells is the middle lamella, which is mainly made of', 'calcium pectate', ['cellulose', 'lignin', 'calcium carbonate'], 'The middle lamella, a layer mainly of calcium pectate, holds neighbouring cells together.');
mc(2, 'cell wall', 'Cytoplasmic connections that pass through the walls of adjacent plant cells are the', 'plasmodesmata', ['pits of bacteria', 'cristae', 'nuclear pores'], 'Plasmodesmata connect the cytoplasm of neighbouring cells through the cell wall.');
mc(2, 'cell size', 'The largest isolated single cell is', 'the egg of an ostrich', ['a human nerve cell', 'a human RBC', 'Mycoplasma'], 'The ostrich egg is the largest isolated single cell. Some nerve cells are the longest, but they are not isolated cells.');
mc(2, 'vacuole', 'The organelle in Amoeba that expels excess water is the', 'contractile vacuole', ['food vacuole', 'lysosome', 'Golgi body'], 'The contractile vacuole removes excess water and some wastes. Food vacuoles form when food is engulfed.');
mc(2, 'chromosomes', 'Disc-shaped structures on either side of the centromere to which spindle fibres attach are', 'kinetochores', ['satellites', 'nucleosomes', 'cristae'], 'Kinetochores are protein discs on the centromere. Satellites are small segments beyond a secondary constriction.');
mc(2, 'ribosomes', 'George Palade is credited with observing', 'ribosomes as dense particles (1953)', ['the Golgi body (1898)', 'the nucleus (1831)', 'the cell membrane model (1972)'], 'Palade saw ribosomes as dense particles in 1953. Golgi described his complex in 1898, Brown found the nucleus in 1831 and Singer and Nicolson gave the membrane model in 1972.');

// ---------------------------------------------------------------- Level 3
mc(3, 'double membrane', 'Which one of these organelles is NOT bounded by two membranes?', 'Lysosome', ['Nucleus', 'Mitochondrion', 'Chloroplast'], 'Nucleus, mitochondria and plastids have double membranes. Lysosomes, vacuoles, ER, Golgi and peroxisomes have a single membrane.');
mc(3, 'own DNA', 'Which pair of organelles contain their own DNA and 70S ribosomes?', 'Mitochondria and chloroplasts', ['Golgi and lysosomes', 'ER and peroxisomes', 'Nucleolus and vacuole'], 'Both mitochondria and chloroplasts have a circular DNA, a few RNAs and 70S ribosomes in the matrix or stroma, and divide by fission.');
mc(3, 'endomembrane', 'Which of the following is NOT part of the endomembrane system?', 'Mitochondria', ['Endoplasmic reticulum', 'Golgi complex', 'Vacuoles'], 'The endomembrane system links ER, Golgi, lysosomes and vacuoles, whose functions are coordinated. Mitochondria, chloroplasts and peroxisomes work separately, so they are excluded.');
mc(3, 'membrane', 'The fluidity of the membrane lets proteins move sideways. NCERT lists which of these as a function helped by this?', 'Formation of intercellular junctions and endocytosis', ['Replication of DNA', 'Synthesis of ATP in the cytoplasm', 'Formation of chromatin'], 'Quasi-fluid nature supports cell growth, formation of intercellular junctions, secretion, endocytosis and cell division. DNA replication and chromatin are nuclear events.');
mc(3, 'membrane', 'Peripheral membrane proteins differ from integral ones in that they', 'lie on the surface of the membrane', ['span the lipid bilayer completely', 'are made only of carbohydrates', 'are found only inside organelles'], 'Peripheral proteins sit on the membrane surface, integral proteins are partly or wholly buried in the bilayer.');
mc(3, 'membrane', 'Movement of a polar solute through a carrier protein down its concentration gradient, with no ATP, is', 'facilitated diffusion', ['simple diffusion', 'active transport', 'endocytosis'], 'Polar molecules cannot cross the non-polar bilayer easily; carrier proteins help them move down their gradient. No energy is spent, and it cannot go uphill.', 'Facilitated diffusion uses a protein, yet it is still passive.');
mc(3, 'prokaryotic cell', 'Ribosomes of a prokaryotic cell are found', 'free in the cytoplasm and associated with the plasma membrane', ['only on a rough ER', 'only inside the nucleoid', 'only in mesosomes enclosed by a membrane'], 'Prokaryotes lack ER. Their 70S ribosomes (about 15 nm by 20 nm) lie in the cytoplasm and are associated with the plasma membrane. Several ribosomes on one mRNA form a polysome.');
mc(3, 'prokaryotic cell', 'Inclusion bodies of bacteria such as phosphate granules and glycogen granules', 'lie free in the cytoplasm without a bounding membrane', ['are enclosed by a double membrane', 'are enclosed by a single membrane', 'are attached to the cell wall'], 'These reserve materials are not bound by any membrane. Gas vacuoles of blue-green, purple and green photosynthetic bacteria are also in this group.');
mc(3, 'prokaryotic cell', 'Which of these is NOT involved in bacterial motility?', 'Fimbriae', ['Flagella', 'Flagellar hook', 'Basal body of the flagellum'], 'Pili and fimbriae are surface structures not involved in motility. Pili are elongated tubular structures made of a special protein; fimbriae are small bristle-like fibres that help bacteria attach to rocks in streams or to host tissue.');
mc(3, 'prokaryotic cell', 'Photosynthetic pigments in cyanobacteria are located in', 'chromatophores formed by membrane extensions into the cytoplasm', ['grana of chloroplasts', 'the nucleoid', 'the cell wall'], 'Cyanobacteria have no chloroplasts. Their membranous extensions called chromatophores contain the pigments.');
mc(3, 'ribosomes', 'The "S" in 70S and 80S stands for', 'Svedberg unit, a measure of sedimentation rate', ['Sulphur content', 'Surface area of the ribosome', 'Size in nanometres'], 'S is the sedimentation coefficient and indirectly measures density and size. It is not additive: 50S + 30S = 70S and 60S + 40S = 80S.', 'Students add the numbers as if S were a mass.');
mc(3, 'ER', 'The lumen of the endoplasmic reticulum divides the cytoplasm into', 'luminal and extra-luminal compartments', ['nuclear and mitochondrial compartments', 'cis and trans compartments', 'grana and stroma compartments'], 'The ER lumen is separate from the rest of the cytoplasm (extraluminal). Cis and trans refer to the Golgi; grana and stroma to chloroplasts.');
mc(3, 'ER', 'Rough ER is most extensive in cells that', 'actively make and secrete proteins', ['store oils and fats', 'make steroid hormones', 'carry out photosynthesis only'], 'Ribosomes on RER make proteins that enter the lumen. Steroid hormone makers have a lot of SER.');
mc(3, 'Golgi', 'The Golgi complex is the major site for the formation of', 'glycoproteins and glycolipids', ['rRNA', 'chlorophyll', 'ATP by oxidative phosphorylation'], 'Golgi attaches sugars to proteins and lipids. rRNA is made in the nucleolus and ATP mainly in mitochondria.');
mc(3, 'lysosomes', 'Lysosomal enzymes work best at', 'acidic pH', ['alkaline pH', 'neutral pH', 'any pH equally'], 'Lysosomal hydrolases are optimally active at acidic pH. They digest carbohydrates, proteins, lipids and nucleic acids.');
mc(3, 'mitochondria', 'The mitochondrial matrix contains', 'a single circular DNA, a few RNAs, 70S ribosomes and enzymes', ['many linear chromosomes with histones', '80S ribosomes only', 'chlorophyll and thylakoids'], 'The matrix has its own genetic system and enzymes. It lacks histone-bound linear chromosomes and 80S ribosomes.');
mc(3, 'mitochondria', 'Which of the following correctly describes mitochondria?', 'Sausage-shaped, 0.2 to 1.0 µm in diameter, dividing by fission', ['Spherical, 5 to 10 µm, dividing by mitosis', 'Disc-shaped, 2 to 4 µm, made de novo from the Golgi', 'Cup-shaped, 10 µm, single-membraned'], 'NCERT gives a diameter of 0.2 to 1.0 µm (average 0.5 µm) and a length of 1.0 to 4.1 µm. They have two membranes and divide by fission.');
mc(3, 'plastids', 'The pigments of chromoplasts are', 'fat-soluble carotenoids', ['chlorophylls', 'water-soluble anthocyanins', 'phycocyanin'], 'Chromoplasts contain carotene and xanthophylls, giving yellow, orange or red colours. Anthocyanin is a water-soluble pigment of the vacuole.', 'Flower colour from anthocyanin is in the vacuole, not in the chromoplast.');
mc(3, 'plastids', 'The stroma of a chloroplast contains', 'enzymes for carbohydrate and protein synthesis, circular DNA and ribosomes', ['only chlorophyll pigments', 'only lipids', 'cristae and matrix'], 'The stroma holds enzymes for making carbohydrates and proteins and small double-stranded circular DNA with 70S ribosomes. Chlorophyll lies in thylakoid membranes.');
mc(3, 'plastids', 'Thylakoids of different grana are connected by', 'stroma lamellae', ['cristae', 'plasmodesmata', 'radial spokes'], 'Stroma lamellae (intergranal thylakoids) join thylakoids of neighbouring grana.');
mc(3, 'cilia and flagella', 'Which of these is true of a eukaryotic flagellum?', 'It is covered by the plasma membrane and arises from a basal body', ['It is made of one protein, flagellin', 'It has a filament, hook and basal body only', 'It lies free in the cytoplasm'], 'Eukaryotic cilia and flagella are outgrowths of the cell membrane and emerge from basal bodies. Flagellin filaments and the hook plus basal body belong to bacteria.');
mc(3, 'cilia and flagella', 'In a 9+2 axoneme, the number of radial spokes is', '9', ['2', '18', '11'], 'Each of the nine peripheral doublets is joined to the central sheath by a radial spoke, so there are nine. The doublets are also linked to one another by linkers.');
mc(3, 'centrosome', 'The two centrioles of a centrosome lie', 'perpendicular to each other', ['parallel to each other', 'one inside the other', 'at the two poles of the cell always'], 'Centrioles lie at right angles to each other, surrounded by amorphous pericentriolar material. They form the basal body of cilia or flagella and the spindle in animal cells.');
mc(3, 'nucleus', 'The nuclear envelope consists of', 'two parallel membranes separated by a perinuclear space', ['a single membrane with pores', 'three membranes with cristae', 'two membranes fused completely'], 'The two membranes enclose a perinuclear space of 10 to 50 nm. The outer membrane is often continuous with the ER and may carry ribosomes.');
mc(3, 'chromosomes', 'Which chromosome type has one very short and one very long arm?', 'Acrocentric', ['Metacentric', 'Sub-metacentric', 'Telocentric'], 'Acrocentric: centromere close to an end. In a telocentric chromosome the centromere is at the tip, so there is only one arm.', 'Telocentric has one arm; acrocentric has two unequal arms.');
mc(3, 'cell theory', 'Which statement is NOT part of the cell theory?', 'All cells have a membrane-bound nucleus', ['All living organisms are made of cells and their products', 'The cell is the structural and functional unit of life', 'New cells arise from pre-existing cells'], 'Prokaryotic cells have no membrane-bound nucleus yet are cells. The other three are the cell theory.');
mc(3, 'cell theory', 'Schwann concluded that animal cells are surrounded by a thin outer layer and that a cell wall is characteristic of', 'plant cells', ['all cells', 'bacteria only', 'animal cells in embryos'], 'Schwann noted the plasma membrane around animal cells and the cell wall as a feature of plants. Combining this with Schleiden\'s work on plants led to the cell theory.');
mc(3, 'plant vs animal cell', 'Centrioles are found in animal cells but usually absent from', 'higher plant cells', ['mammalian cells', 'ciliated epithelial cells', 'protozoan cells'], 'Higher plants form spindles without centrioles, whereas animal, ciliated and protozoan cells have them.');


mc(1, 'cell theory', 'Which scientist first saw and described a live cell?', 'Anton von Leeuwenhoek', ['Camillo Golgi', 'George Palade', 'Robert Brown'], 'Leeuwenhoek was the first to see and describe a live cell. Brown found the nucleus, Golgi the Golgi complex and Palade the ribosome particles.');
mc(1, 'prokaryotic cell', 'Which of these is a prokaryote?', 'Blue-green alga (cyanobacterium)', ['Amoeba', 'Yeast', 'Paramecium'], 'Bacteria, cyanobacteria and mycoplasma are prokaryotes. Amoeba, yeast and Paramecium are eukaryotes with a true nucleus.');
mc(1, 'ER', 'The network of tubular structures extending from the nuclear membrane through the cytoplasm is the', 'endoplasmic reticulum', ['Golgi apparatus', 'centrosome', 'thylakoid'], 'The ER is a network of tiny tubes and flattened sacs, with a lumen, continuous with the outer nuclear membrane.');
mc(1, 'nucleus', 'The nucleus contains threadlike stained fibres called', 'chromatin', ['cristae', 'grana', 'cilia'], 'Chromatin, stained by basic dyes, is made of DNA and proteins. It condenses into chromosomes during cell division.');
mc(1, 'vacuole', 'The membrane-bound space of a plant cell holding sap is the', 'vacuole', ['ribosome', 'centriole', 'nucleolus'], 'The vacuole holds water, sap, excretory products and other materials not useful to the cell.');
mc(1, 'membrane', 'The main molecules forming the basic framework of the plasma membrane are', 'phospholipids', ['nucleotides', 'starch molecules', 'cellulose fibres'], 'Phospholipids form the bilayer; proteins and some cholesterol and carbohydrates lie in or on it.');
mc(2, 'mitochondria', 'Number of membranes around a mitochondrion is', 'two', ['one', 'three', 'none'], 'A mitochondrion has an outer smooth membrane and an inner membrane forming cristae, two in all.');
mc(2, 'prokaryotic cell', 'Which shape is called a vibrio?', 'Comma-shaped', ['Rod-shaped', 'Spherical', 'Spiral'], 'Bacillus is rod, coccus is spherical, vibrio is comma-shaped and spirillum is spiral.', 'Vibrio and spirillum are often swapped.');
mc(2, 'cytoskeleton', 'Which of these is NOT a part of the cytoskeleton?', 'Cristae', ['Microtubules', 'Microfilaments', 'Intermediate filaments'], 'The cytoskeleton is a network of protein filaments (microtubules, microfilaments and intermediate filaments) giving support and motility and keeping shape. Cristae are mitochondrial membrane folds.');
mc(2, 'microbodies', 'Microbodies are', 'minute membrane-bound vesicles with enzymes, found in plant and animal cells', ['double-membraned, with DNA', 'non-membranous granules of RNA', 'found only in prokaryotes'], 'Microbodies such as peroxisomes are small single-membrane sacs with various enzymes.');
mc(2, 'chromosomes', 'The chromosome region that holds the two chromatids is the', 'centromere', ['satellite', 'telomere only', 'nucleolus'], 'The primary constriction, the centromere, holds sister chromatids together and carries the kinetochores.');
mc(2, 'Golgi', 'Who described the Golgi complex?', 'Camillo Golgi in 1898', ['Robert Brown in 1831', 'Rudolf Virchow in 1855', 'George Palade in 1953'], 'Golgi saw densely stained reticular structures near the nucleus in 1898; they were later named after him.');

// assertions and statements L3
asr(3, 'ribosomes', 'Prokaryotic and eukaryotic ribosomes have different sizes.', 'Eukaryotic ribosomes are 80S while prokaryotic ones are 70S.', 0, 'The difference is exactly that: 80S (60S + 40S) in the eukaryotic cytoplasm, 70S (50S + 30S) in bacteria. R states the facts that make A true, so R explains A.');
asr(3, 'ER', 'Rough ER looks rough under the electron microscope.', 'Ribosomes are attached to its outer surface.', 0, 'Ribosomes on the cytoplasmic face give the rough look. R is the correct reason.');
asr(3, 'lysosomes', 'Lysosomal enzymes can digest almost all biomolecules.', 'Lysosomes contain only proteases.', 2, 'A is true: they hold lipases, proteases, carbohydrases and nucleases. R is false because they hold many kinds of hydrolases, not only proteases.');
asr(3, 'mitochondria', 'Mitochondria can make some of their own proteins.', 'They contain 80S ribosomes in the matrix.', 2, 'A is true because the matrix has DNA, RNA and ribosomes. R is false: the ribosomes are 70S, like bacterial ones.', 'The 70S vs 80S swap is a favourite trap.');
asr(3, 'cell wall', 'Neighbouring plant cells are held together even after their walls thicken.', 'The middle lamella, rich in calcium pectate, glues neighbouring cells.', 0, 'The middle lamella is the cementing layer between cells. It is the reason cells stay attached, so R explains A.');
asr(3, 'membrane', 'Phospholipids form a bilayer in water.', 'The hydrophilic heads face the aqueous medium and the hydrophobic tails face each other.', 0, 'The bilayer forms because of this arrangement, so R explains A.');
stm(3, 'prokaryotic cell', 'Plasmids are a part of the bacterial chromosome.', 'Plasmids can confer antibiotic resistance.', 3, 'Statement I is wrong: plasmids lie outside the genomic DNA. Statement II is right.');
stm(3, 'double membrane', 'Nucleus, mitochondria and plastids are double-membrane bound.', 'The Golgi complex has a double membrane.', 2, 'I is correct. II is wrong; the Golgi is made of single-membrane cisternae.');
stm(3, 'cilia and flagella', 'Bacterial flagella and eukaryotic flagella are structurally the same.', 'Eukaryotic flagella have a 9+2 axoneme.', 3, 'NCERT says bacteria also have flagella but they are structurally different (filament, hook, basal body). II is true.');
stm(3, 'chromosomes', 'The centromere holds two chromatids together.', 'Kinetochores are found on either side of the centromere.', 0, 'Both are true: sister chromatids are joined at the centromere, and kinetochores form on its two sides as disc-shaped structures.');

// ---------------------------------------------------------------- Level 4
mc(4, 'double membrane', 'Select the group in which ALL organelles are single-membrane bound.', 'Lysosome, Golgi body, vacuole, peroxisome', ['Nucleus, Golgi body, lysosome, vacuole', 'Mitochondrion, ER, vacuole, lysosome', 'Chloroplast, Golgi body, peroxisome, ER'], 'Lysosome, Golgi, vacuole and peroxisome (a microbody) all have one membrane. The other groups each contain a double-membraned organelle (nucleus, mitochondrion or chloroplast).', 'Each wrong option hides just one double-membrane organelle.');
mc(4, 'endomembrane', 'An enzyme made on ribosomes of the rough ER is to be secreted out of the cell. Choose the correct route.', 'RER lumen → Golgi cis face → Golgi trans face → secretory vesicle → plasma membrane', ['SER → lysosome → plasma membrane', 'Free ribosome → nucleus → Golgi → plasma membrane', 'RER → mitochondrion → plasma membrane'], 'Proteins enter the RER lumen while being made, go to the cis face of Golgi, are modified, leave from the trans face in vesicles and fuse with the plasma membrane. Free ribosomes make cytosolic proteins; lysosomes and mitochondria are not on the secretory route.');
mc(4, 'membrane', 'A drug stops the cell making ATP. Which transport will stop first?', 'Movement of Na<sup>+</sup> out and K<sup>+</sup> into the cell against gradients', ['Entry of O<sub>2</sub> by simple diffusion', 'Entry of water by osmosis', 'Facilitated entry of glucose down its gradient'], 'Only active transport (the Na<sup>+</sup>/K<sup>+</sup> pump) uses ATP. Diffusion, osmosis and facilitated diffusion are driven by the gradient alone, so they continue for a time.', 'Facilitated diffusion has a protein but no ATP.');
mc(4, 'membrane', 'Which statement about the membrane lipids in the fluid mosaic model is correct?', 'Lipids move laterally within their own layer', ['Lipids are fixed in place and only proteins move', 'The heads of both layers face each other', 'The membrane is a rigid sandwich of protein–lipid–protein'], 'The Singer–Nicolson model has a quasi-fluid bilayer: lipids and proteins move laterally. The heads face the watery sides. The older sandwich model was static.');
mc(4, 'prokaryotic cell', 'Which of the following is correct for a typical bacterial cell envelope?', 'Three tightly bound layers: glycocalyx, cell wall and plasma membrane, acting as one protective unit', ['A cell wall only, since the plasma membrane is absent', 'Glycocalyx inside the plasma membrane', 'Two layers: cell wall and nuclear membrane'], 'The envelope is made of glycocalyx (outermost), cell wall and plasma membrane. Each has a distinct function, but they work as one unit.');
mc(4, 'prokaryotic cell', 'Which of the following is an advantage of mesosomes?', 'They increase the surface area and enzyme content of the membrane', ['They store genetic information', 'They contain chlorophyll in all bacteria', 'They make the cell wall rigid by cellulose deposition'], 'More membrane means more room for respiratory enzymes; mesosomes also take part in DNA replication and cell wall formation. Bacterial walls have no cellulose.');
mc(4, 'cell size', 'Arrange these in increasing order of size: Mycoplasma, bacterium (typical), human RBC, ostrich egg', 'Mycoplasma &lt; bacterium &lt; human RBC &lt; ostrich egg', ['bacterium &lt; Mycoplasma &lt; human RBC &lt; ostrich egg', 'Mycoplasma &lt; human RBC &lt; bacterium &lt; ostrich egg', 'Mycoplasma &lt; bacterium &lt; ostrich egg &lt; human RBC'], 'About 0.3 µm &lt; 3 to 5 µm &lt; 7 µm &lt; egg (many centimetres). A human RBC is about 7 µm, bigger than a typical bacterium.', 'Many students think RBC is smaller than bacteria because it is microscopic.');
mc(4, 'plastids', 'A leaf cell and a ripe tomato cell both contain plastids. Which statement is correct?', 'Leaf: chloroplasts with chlorophyll; ripe tomato: chromoplasts with carotenoids', ['Both have chloroplasts with the same pigments', 'Leaf: leucoplasts; ripe tomato: amyloplasts', 'Both lack plastids because they have vacuoles'], 'Chloroplasts turn into chromoplasts as fruits ripen. The red of tomato is the carotenoid lycopene. Leucoplasts are colourless.');
mc(4, 'ribosomes', 'A cell has 80S ribosomes in its cytoplasm. Which other site in the same cell is expected to have 70S ribosomes?', 'Matrix of mitochondria', ['Lumen of the ER', 'Nucleoplasm only', 'Perinuclear space'], 'Mitochondria and plastids keep bacterial-type 70S ribosomes. ER ribosomes are attached to the outside and are 80S.');
mc(4, 'centrosome', 'Which pair of structures has the SAME microtubule arrangement?', 'Centriole and basal body', ['Centriole and cilium axoneme', 'Basal body and flagellum axoneme', 'Cilium and bacterial flagellum'], 'Centrioles and basal bodies are both 9 triplets with no central pair (9+0, cartwheel). Axonemes are 9+2 doublets. Bacterial flagella have no microtubules.', 'Basal body vs axoneme is a classic mix-up.');
mc(4, 'cilia and flagella', 'Which one correctly differentiates cilia from flagella?', 'Cilia are short and work like oars; flagella are longer and mostly cause cell movement', ['Cilia are bacterial; flagella are eukaryotic', 'Cilia have 9+0; flagella have 9+2', 'Cilia are inside the cell; flagella are outside'], 'Both are eukaryotic outgrowths with 9+2 axonemes; they differ in length and beat pattern. Bacterial flagella are a different structure.');
mc(4, 'nucleus', 'Which statement is true of the nucleolus?', 'It is not membrane bound and its content is continuous with the nucleoplasm', ['It is bound by a single membrane', 'It is bound by a double membrane with pores', 'It makes proteins directly'], 'The nucleolus is a spherical structure with no membrane. It makes rRNA, and ribosome parts are assembled with proteins; proteins are made in the cytoplasm.');
mc(4, 'nucleus', 'Which of the following has NO nucleus at maturity?', 'Mammalian erythrocyte and sieve tube cell', ['Paramecium and human neuron', 'Skeletal muscle fibre and guard cell', 'Hepatocyte and mammalian RBC precursor in marrow'], 'Mature RBCs of most mammals and sieve tube cells of vascular plants lose their nuclei. Neurons, muscle fibres and guard cells keep them.');
mc(4, 'chromosomes', 'A chromosome shows a secondary constriction near one end, giving a small round knob. This knob is called a', 'satellite', ['kinetochore', 'chromomere', 'telomere'], 'The segment beyond a secondary constriction is the satellite. Kinetochores sit at the centromere (primary constriction).', 'Do not confuse secondary constriction with the centromere.');
asr(4, 'prokaryotic cell', 'Cyanobacteria can photosynthesise although they have no chloroplasts.', 'Their pigments are held in membranous extensions called chromatophores.', 0, 'Photosynthetic pigments sit in chromatophores, which are extensions of the plasma membrane into the cytoplasm. So R explains A.');
asr(4, 'membrane', 'Proteins of the plasma membrane can move sideways within it.', 'The lipid bilayer has a quasi-fluid nature.', 0, 'Because the bilayer is quasi-fluid, proteins and lipids can shift laterally. This is the core of the fluid mosaic model, so R explains A.');
asr(4, 'chloroplast', 'Stroma lamellae connect different grana of a chloroplast.', 'The stroma lamellae are flattened membranous tubes that contain the enzymes of carbohydrate synthesis.', 2, 'A is true: stroma lamellae (intergranal thylakoids) join the grana. R is false: the enzymes for carbohydrate and protein synthesis are in the fluid stroma, not in the lamellae.', 'Enzymes are in the stroma, pigments in thylakoids.');
asr(4, 'vacuole', 'The tonoplast helps plant cells accumulate ions inside the vacuole.', 'Tonoplast facilitates transport of ions against concentration gradients.', 0, 'That is exactly the way it concentrates ions, so R explains A.');
stm(4, 'ribosomes', 'In eukaryotes 60S + 40S = 100S.', 'Ribosomes of mitochondria are 70S.', 3, 'I is wrong because S values are not additive; the whole is 80S. II is correct.');
stm(4, 'endomembrane', 'Peroxisomes are part of the endomembrane system.', 'Lysosomes are formed by packaging in the Golgi.', 3, 'I is wrong; peroxisomes (microbodies) work independently of the coordinated ER–Golgi–lysosome–vacuole system. II is correct.');
stm(4, 'centrosome', 'Centrioles are surrounded by pericentriolar material.', 'The centriole hub is connected to the peripheral triplets by radial spokes.', 0, 'Both match NCERT: the centrosome has two centrioles in amorphous pericentriolar material; the proteinaceous hub is linked to triplets by radial spokes.');
stm(4, 'mitochondria', 'The outer membrane of a mitochondrion forms cristae.', 'The inner membrane has enzymes specific to it.', 3, 'The inner membrane, not the outer, forms cristae, so I is wrong. II is true: the two membranes have their own specific enzymes.');
stm(4, 'plastids', 'Elaioplasts store oils and fats.', 'Aleuroplasts store starch.', 2, 'Elaioplasts: oils and fats (true). Aleuroplasts store proteins; amyloplasts store starch. II is wrong.');
match(4, 'organelles', 'm1', 'Organelle and its feature', ['A. Mitochondria', 'B. Golgi apparatus', 'C. Lysosome', 'D. Nucleolus'], ['p. Hydrolytic enzymes, acidic pH', 'q. Cristae and matrix', 'r. cis and trans faces', 's. Site of rRNA synthesis'], 'A-q, B-r, C-p, D-s', ['A-r, B-q, C-p, D-s', 'A-q, B-p, C-r, D-s', 'A-q, B-r, C-s, D-p'], 'Mitochondria have cristae; Golgi has cis and trans faces; lysosomes have acid hydrolases; the nucleolus makes rRNA.');
match(4, 'chromosomes', 'm2', 'Centromere position and chromosome type', ['A. Middle', 'B. Slightly away from the middle', 'C. Close to one end', 'D. At the terminal end'], ['p. Telocentric', 'q. Acrocentric', 'r. Sub-metacentric', 's. Metacentric'], 'A-s, B-r, C-q, D-p', ['A-r, B-s, C-q, D-p', 'A-s, B-r, C-p, D-q', 'A-s, B-q, C-r, D-p'], 'Metacentric (middle), sub-metacentric (slightly off), acrocentric (near end), telocentric (terminal).');
match(4, 'plastids', 'm3', 'Plastid and its content', ['A. Amyloplast', 'B. Elaioplast', 'C. Aleuroplast', 'D. Chromoplast'], ['p. Proteins', 'q. Carotenoids', 'r. Starch', 's. Oils and fats'], 'A-r, B-s, C-p, D-q', ['A-s, B-r, C-p, D-q', 'A-r, B-s, C-q, D-p', 'A-p, B-s, C-r, D-q'], 'Amyloplasts store starch; elaioplasts oils; aleuroplasts proteins; chromoplasts carry carotenoid pigments.');
match(4, 'scientists', 'm4', 'Scientist and contribution', ['A. Robert Brown', 'B. Camillo Golgi', 'C. George Palade', 'D. Singer and Nicolson'], ['p. Dense ribosome particles', 'q. Fluid mosaic model', 'r. Nucleus', 's. Reticular structures, 1898'], 'A-r, B-s, C-p, D-q', ['A-s, B-r, C-p, D-q', 'A-r, B-s, C-q, D-p', 'A-p, B-s, C-r, D-q'], 'Brown: nucleus (1831); Golgi: stained reticular structures (1898); Palade: ribosomes (1953); Singer and Nicolson: fluid mosaic model (1972).');

// passages
pass('p1', 'Passage: a mystery organism', 'A unicellular organism was found in pond water. Under the electron microscope it has no nucleus bounded by a membrane, its DNA is a single circular molecule lying in a region of the cytoplasm, and small circular DNA pieces are also present. The cytoplasm has ribosomes about 15 nm × 20 nm. It has a flagellum made of a filament, a hook and a basal body, and the cell is surrounded by a loose sheath outside its wall. Membrane infoldings are seen close to the point where DNA is attached.');
pq('p1', 3, 'prokaryotic cell', 'The type of ribosome and the nature of the sheath in this organism are', '70S ribosomes and a slime layer', ['80S ribosomes and a capsule', '70S ribosomes and a capsule', '80S ribosomes and a slime layer'], 'The ribosomes (15 × 20 nm, no nucleus) are 70S, as in all prokaryotes. A loose sheath is a slime layer; a thick tough one would be a capsule.');
pq('p1', 3, 'prokaryotic cell', 'The membrane infoldings near the DNA attachment are most likely', 'mesosomes', ['cristae', 'cisternae', 'grana'], 'Mesosomes are plasma membrane infoldings that help in DNA replication and its distribution. Cristae, cisternae and grana belong to eukaryotic organelles.');
pq('p1', 4, 'prokaryotic cell', 'The small circular DNA pieces are expected to', 'carry traits such as antibiotic resistance and lie outside the main chromosome', ['be enclosed in a nuclear envelope', 'carry only ribosomal RNA genes', 'be made of histones and DNA'], 'These are plasmids. Prokaryotic DNA is naked, without histone packaging, and not membrane enclosed.');
pass('p2', 'Passage: an unknown organelle', 'A cell biologist isolates an organelle that has two membranes. The inner membrane is thrown into many folds that project into a fluid space. This space holds a circular DNA, ribosomes smaller than those in the cytoplasm, and enzymes. The organelle is rod-like, 0.5 µm in diameter, and is seen dividing in two when the cell grows.');
pq('p2', 3, 'mitochondria', 'The organelle is the', 'mitochondrion', ['chloroplast', 'Golgi body', 'lysosome'], 'Folds called cristae and a matrix with DNA and 70S ribosomes identify a mitochondrion. Chloroplasts have thylakoids; the Golgi and lysosomes have a single membrane.');
pq('p2', 4, 'mitochondria', 'The ribosomes in this organelle are', '70S, made of 50S and 30S subunits', ['80S, made of 60S and 40S subunits', '70S, made of 60S and 40S subunits', '100S, made of 60S and 40S subunits'], 'Mitochondrial ribosomes are bacterial-type 70S (50S + 30S). Eukaryotic 80S is 60S + 40S; S values are not simply added.');
pq('p2', 4, 'mitochondria', 'Its division mode is', 'binary fission', ['mitosis', 'meiosis', 'budding from the ER'], 'Mitochondria divide by fission like bacteria, which is why this organelle is compared with them.', 'Mitosis is for cells, not organelles.');

// ---------------------------------------------------------------- Level 5
mc(5, 'double membrane', 'A cell structure listed below is both (a) not bounded by any membrane and (b) made of protein only or of RNA with protein. Choose the correct set.', 'Ribosome, centriole, microtubule', ['Ribosome, nucleolus, lysosome', 'Centriole, Golgi cisterna, microfilament', 'Nucleolus, mitochondrion, ribosome'], 'Ribosomes (rRNA + protein), centrioles (tubulin) and microtubules have no membrane. A lysosome, Golgi cisterna and mitochondrion are membrane bound. The nucleolus has no membrane but includes DNA, RNA and protein, so it does not fit (b).', 'Nucleolus is membrane-free but not "protein or RNA with protein" only.');
mc(5, 'prokaryotic cell', 'Which of the following is a feature of the bacterial genome in NCERT\'s account?', 'A single chromosome of naked DNA in a nucleoid, with plasmids outside it', ['Several chromosomes held with histones and enclosed by a nuclear envelope', 'A single chromosome enclosed in a nuclear envelope with pores', 'Two linear chromosomes joined at a centromere'], 'Prokaryotes have no nuclear envelope; the genomic DNA is naked (no histones) in the nucleoid. Plasmids lie outside.');
mc(5, 'cell envelope', 'A researcher treats bacterial cells so as to remove the outermost layer of the envelope only. The cell is still surrounded by a wall and membrane. Which layer was removed?', 'Glycocalyx', ['Plasma membrane', 'Cell wall', 'Mesosome'], 'The outermost layer of the three-layered envelope is the glycocalyx (slime layer or capsule); the cell wall comes next, then the plasma membrane. Mesosomes are folds of the membrane, not an envelope layer.');
mc(5, 'plastids', 'A scientist measures a plastid 7 µm long and 3 µm wide with thylakoid piles and DNA. Which statement is consistent?', 'It is a chloroplast, as their size is 5 to 10 µm by 2 to 4 µm', ['It is a mitochondrion, as they are 5 to 10 µm long', 'It is a ribosome, which is 3 µm across', 'It is a Golgi complex, which has grana'], 'NCERT gives chloroplast length 5 to 10 µm and width 2 to 4 µm. Mitochondria are 1.0 to 4.1 µm long. Ribosomes are about 20 nm. Grana belong to chloroplasts, not Golgi.');
mc(5, 'membrane', 'Why is the human erythrocyte a good cell for studying the plasma membrane?', 'Mature mammalian RBCs have no nucleus or membrane-bound organelles, so the only membrane is the plasma membrane', ['It has the most mitochondria', 'It has a large Golgi body', 'It has a cell wall that can be peeled off'], 'With no nucleus and organelles, a ruptured RBC gives a pure plasma membrane. RBCs have none of the other options.');
mc(5, 'ER', 'Which pair is correctly matched?', 'Smooth ER: steroidal hormone synthesis in animal cells', ['Rough ER: synthesis of lipids and ATP', 'Smooth ER: ribosome attachment', 'Golgi: synthesis of proteins from amino acids'], 'SER makes lipids and steroid hormones; RER has ribosomes and handles proteins; Golgi processes and packages and does not translate mRNA.');
mc(5, 'nucleus', 'Which of the following best explains why cells making large amounts of protein have a larger nucleolus?', 'More rRNA must be made for many ribosomes', ['The nucleolus makes proteins directly', 'The nucleolus packages proteins into vesicles', 'The nucleolus contains the Golgi'], 'Protein synthesis needs ribosomes, whose RNA is made in the nucleolus. The nucleolus itself does not translate or package.');
mc(5, 'cilia and flagella', 'In a cross-section of a cilium, which count is correct?', '9 peripheral doublets, 2 central singlets, 9 radial spokes', ['9 peripheral triplets, 0 central tubules, 9 radial spokes', '9 peripheral doublets, 2 central singlets, 2 radial spokes', '2 peripheral doublets, 9 central singlets, 9 radial spokes'], 'The axoneme is 9 doublets + 2 central; spokes join each doublet to the central sheath; linkers join the doublets. Triplets with no central tubule describe the centriole and basal body.', 'Doublets in the axoneme; triplets in the basal body.');
mc(5, 'chromosomes', 'In which case does the chromosome have only ONE arm visible after the centromere?', 'Telocentric', ['Acrocentric', 'Sub-metacentric', 'Metacentric'], 'With a terminal centromere there is only one arm. An acrocentric chromosome has a very short second arm.');
mc(5, 'ribosomes', 'A student says: "S in 40S + 60S = 80S shows that Svedberg units add up simply." A better correction is', 'Svedberg units depend on size and shape; sedimentation does not add linearly', ['40 + 60 = 100, so 80S is a printing error', 'S stands for sulphur content, which is halved on assembly', 'Ribosomes lose half of their mass on joining'], 'The S value is a rate of sedimentation and is affected by shape as well as mass, so subunits do not add. This is why 50S + 30S = 70S.');
asr(5, 'cell theory', 'Cell theory in its original form by Schleiden and Schwann was incomplete.', 'It did not say how new cells arise.', 0, 'Virchow supplied the missing point that new cells arise from existing cells. R explains why A is true.');
asr(5, 'membrane', 'Integral proteins are difficult to remove from a membrane.', 'They are partially or wholly buried in the lipid bilayer.', 0, 'Their burial in the hydrophobic core is why mild washing does not detach them.');
stm(5, 'chloroplast', 'The ribosomes of chloroplast are smaller than the cytoplasmic ribosomes of the same cell.', 'Chloroplast DNA is double-stranded and circular.', 0, 'Chloroplast ribosomes are 70S compared with 80S in the cytoplasm, and the DNA is a small double-stranded circle. Both are right.');
stm(5, 'ER and nuclear envelope', 'The outer nuclear membrane is continuous with the ER.', 'The inner nuclear membrane bears ribosomes on its surface.', 2, 'NCERT says the outer membrane usually remains continuous with the ER and also bears ribosomes. II is wrong because ribosomes are on the outer, not inner, membrane.');
stm(5, 'vacuole', 'In some plant cells the vacuole may occupy up to 90 per cent of the cell volume.', 'The vacuole is bounded by a double membrane called the tonoplast.', 2, 'I is true. The tonoplast is a single membrane, so II is wrong.');

// ===== EXPANSION (round 2) =====
const hm = (level, sub, q, correct, wrongs, sol, trap) => mc(level, sub, q, correct, wrongs, sol, trap, 'statements');
// ---- Level 2
mc(2, 'cell theory', 'Cell theory was put forward by Schleiden and Schwann. Which statement about them is correct?', 'Schleiden was a botanist and Schwann a zoologist', ['Both were botanists', 'Schleiden was a zoologist and Schwann a botanist', 'Both were physicians who studied bacteria'], 'Matthias Schleiden (a German botanist) and Theodor Schwann (a British physiologist and zoologist) together proposed that the bodies of plants and animals are composed of cells and their products.');
mc(2, 'cell theory', 'The term "cell" was first used by', 'Robert Hooke, for the compartments he saw in a slice of cork', ['Anton von Leeuwenhoek, for living bacteria', 'Robert Brown, for the nucleus', 'Rudolf Virchow, for pre-existing cells'], 'Robert Hooke described the box-like compartments of cork in 1665 and named them cells. Leeuwenhoek first saw and described a live cell.', 'Hooke named the cell; Leeuwenhoek saw a living one.');
mc(2, 'prokaryotic cell', 'A thin loose layer of glycocalyx around a bacterium is called a', 'slime layer', ['capsule', 'mesosome', 'plasmid'], 'The glycocalyx may be a loose sheath, the slime layer, or a thick tough layer, the capsule.', 'Capsule is the thick layer; slime layer is loose.');
mc(2, 'prokaryotic cell', 'The bacterial flagellum has three parts. These are', 'filament, hook and basal body', ['filament, axoneme and basal body', 'hook, axoneme and sheath', 'filament, hook and sheath only'], 'A bacterial flagellum consists of the filament (longest), a hook and a basal body that anchors it in the envelope. The 9+2 axoneme belongs to a eukaryotic flagellum.');
mc(2, 'ER', 'Steroidal hormones are synthesised in animal cells in the', 'smooth endoplasmic reticulum', ['rough endoplasmic reticulum', 'Golgi complex only', 'lysosomes'], 'The SER is the major site of lipid synthesis; in animal cells lipid-like steroid hormones are made there.');
mc(2, 'Golgi', 'The Golgi complex has a convex face and a concave face. The convex face is also called the', 'cis or forming face', ['trans or maturing face', 'luminal face', 'tonoplast face'], 'The cis (convex) face receives vesicles from the ER; the trans (concave) face gives off vesicles after modification.');
mc(2, 'lysosomes', 'Lysosomes arise in the cell by', 'packaging in the Golgi apparatus', ['budding from mitochondria', 'division of the nucleolus', 'fusion of ribosomes'], 'Lysosomes are membrane-bound vesicles formed by the process of packaging in the Golgi apparatus. They are rich in hydrolytic enzymes.');
mc(2, 'vacuole', 'In some plant cells the vacuole can occupy up to what part of the cell volume?', '90 per cent', ['10 per cent', '50 per cent', '30 per cent'], 'The vacuole of a plant cell is bounded by the tonoplast and can take up to 90 per cent of the volume.');
mc(2, 'mitochondria', 'Which part of a mitochondrion contains a circular DNA molecule, 70S ribosomes and enzymes of the Krebs cycle?', 'The matrix', ['The outer membrane', 'The intermembrane space', 'The cristae membrane only'], 'The matrix is the inner compartment. NCERT lists a single circular DNA, a few RNA molecules, ribosomes and components for protein synthesis there.');
mc(2, 'plastids', 'Elaioplasts are leucoplasts that store', 'oils and fats', ['starch', 'proteins', 'carotenoids'], 'Amyloplasts store starch, elaioplasts store oils and fats, and aleuroplasts store proteins.', 'Each name tells the stored product: amylo (starch), elaio (oil), aleuro (protein).');
mc(2, 'nucleus', 'Who first described the cell nucleus?', 'Robert Brown', ['Schleiden', 'Camillo Golgi', 'Flemming'], 'Robert Brown described the nucleus; Flemming later gave the name chromatin to the material that stains with basic dyes.');
mc(2, 'chromosomes', 'A chromosome with the centromere very close to one end, so that one arm is extremely short, is', 'acrocentric', ['metacentric', 'sub-metacentric', 'telocentric'], 'Metacentric: middle. Sub-metacentric: slightly away from the middle. Acrocentric: close to the end. Telocentric: terminal centromere.', 'Telocentric has a terminal centromere; acrocentric has a very short arm.');

// ---- Level 3
mc(3, 'prokaryotic cell', 'Mesosomes of a bacterium are formed by the', 'extension of the plasma membrane into the cell in the form of vesicles, tubules and lamellae', ['fusion of ribosomes in the cytoplasm', 'folding of the cell wall only', 'condensation of the nucleoid'], 'Mesosomes are infoldings of the plasma membrane. They help in cell wall formation, DNA replication and distribution to daughter cells, respiration and secretion, and they increase the surface area.');
mc(3, 'prokaryotic cell', 'Pili and fimbriae of bacteria differ in that', 'pili are tubular structures of a special protein, while fimbriae are bristle-like fibres that help attachment', ['pili are made of cellulose and fimbriae of chitin', 'pili cause motility by a 9+2 arrangement', 'fimbriae are the plasmids of the cell'], 'NCERT describes pili as elongated tubular structures made of a special protein, and fimbriae as small bristle-like fibres that help bacteria attach to rocks in streams and host tissues.', 'Flagella give motility; pili and fimbriae do not have a 9+2 axoneme.');
mc(3, 'prokaryotic cell', 'Which of the following is correct for the ribosomes of a bacterial cell?', 'They are 70S and occur freely in the cytoplasm or attached to the plasma membrane', ['They are 80S and bound to the rough ER', 'They are 70S and enclosed in a nuclear envelope', 'They are 80S and found only inside mesosomes'], 'Prokaryotic ribosomes are 70S (50S + 30S) and lie in the cytoplasm or attached to the plasma membrane. There is no ER in a prokaryote.');
mc(3, 'prokaryotic cell', 'A bacterium carrying a plasmid with a gene for antibiotic resistance is cultured with that antibiotic. The plasmid is', 'extra-chromosomal circular DNA that gives the cell a phenotype, such as resistance', ['a part of the nucleoid essential for all life processes', 'a linear chromosome with histones', 'a ribosomal subunit'], 'Plasmids are small circular DNA outside the genomic DNA. They confer unique phenotypic characters, such as resistance to antibiotics, but are not needed for basic life.');
mc(3, 'prokaryotic cell', 'Which one of the following statements about the genetic material of a bacterial cell is correct?', 'It is not enveloped by a nuclear membrane and forms the nucleoid', ['It lies inside a double nuclear envelope', 'It is organised into histone nucleosomes as in eukaryotes', 'It is a linear molecule with many chromosomes'], 'The genomic DNA of a bacterium is a single circular molecule without a nuclear membrane, forming a nucleoid. Histone nucleosomes are for eukaryotic chromatin.');
mc(3, 'cell wall', 'The plant cell wall layer that is formed on the inner side after the cell matures and stops growing is the', 'secondary wall', ['primary wall', 'middle lamella', 'plasma membrane'], 'The primary wall is capable of growth and becomes thinner as the cell matures. The secondary wall is laid inside it. The middle lamella is the outermost cementing layer.');
mc(3, 'cell wall', 'Which pair of chemical components is correct for the walls of algae and plants?', 'Algae: cellulose, galactans, mannans and calcium carbonate; plants: cellulose, hemicellulose, pectins and proteins', ['Algae: chitin; plants: peptidoglycan', 'Algae: lignin only; plants: cellulose only', 'Algae: peptidoglycan; plants: lipids and proteins'], 'This is as described in the NCERT account of the eukaryotic cell wall.');
mc(3, 'ER', 'Which statement about the endoplasmic reticulum is correct?', 'Its lumen separates the cell into luminal and extra-luminal (cytoplasmic) compartments', ['It is bounded by two membranes', 'It is found only in prokaryotic cells', 'It consists of flat sacs stacked like a pile of coins'], 'The ER is a network of tubules and cisternae with a single membrane that divides the intracellular space into luminal and extra-luminal compartments. Stacked flat sacs describe the Golgi.');
mc(3, 'ER', 'The ribosomes of the rough endoplasmic reticulum are attached to its', 'outer surface (cytoplasmic side)', ['luminal surface', 'surface facing the Golgi only', 'internal matrix'], 'Ribosomes sit on the cytoplasmic surface. They make proteins that enter the lumen for secretion or membrane insertion.');
mc(3, 'Golgi', 'Which of these is correct about the Golgi complex?', 'It consists of flat disc-shaped cisternae stacked parallel to each other', ['It has a continuous double membrane with pores', 'It is the site of ATP synthesis', 'It contains 70S ribosomes on its surface'], 'The Golgi has many flat, disc-shaped sacs (cisternae) with diameter 0.5 to 1.0 micrometre. It is a single-membrane structure. It packages and modifies material from the ER.');
mc(3, 'lysosomes', 'Which of the following is NOT a hydrolytic enzyme type listed for lysosomes?', 'Oxidases', ['Lipases', 'Proteases', 'Carbohydrases'], 'Lysosomal enzymes, active at an acidic pH, include lipases, proteases, carbohydrases and nucleases. Oxidases belong to peroxisomes (microbodies).', 'Peroxisomes are for oxidative reactions.');
mc(3, 'vacuole', 'The vacuolar membrane facilitates transport of ions and other materials against concentration gradients into the vacuole. This is the', 'tonoplast', ['plasmalemma', 'inner mitochondrial membrane', 'nuclear envelope'], 'The single membrane of the plant vacuole is the tonoplast. This accumulation against a gradient needs energy.');
mc(3, 'mitochondria', 'Mitochondria divide by', 'fission', ['budding from the nucleus', 'mitosis with a spindle', 'formation of a cell plate'], 'Mitochondria are semi-autonomous: they have their own circular DNA and 70S ribosomes, and divide by fission.');
mc(3, 'mitochondria', 'In a mitochondrion, the two aqueous compartments are', 'the matrix and the intermembrane space', ['the lumen and the stroma', 'the cisternae and the matrix', 'the perinuclear space and the matrix'], 'The outer and inner membranes enclose the intermembrane space between them; the inner membrane encloses the matrix.');
mc(3, 'plastids', 'The chloroplast has a double membrane. Inside it, the fluid-filled space is the', 'stroma', ['matrix', 'lumen of the ER', 'granum'], 'The stroma of a chloroplast holds enzymes for carbohydrate and protein synthesis, small circular DNA and 70S ribosomes. The thylakoids lie within it.');
mc(3, 'plastids', 'Chromoplasts contain the pigments', 'carotene and xanthophylls, which give yellow, orange or red colours', ['chlorophyll a and b', 'anthocyanin only', 'phycocyanin'], 'Chromoplasts have fat-soluble carotenoid pigments such as carotene and xanthophylls. Chlorophylls are in chloroplasts.');
mc(3, 'ribosomes', 'A eukaryotic ribosome has subunits of', '60S and 40S', ['50S and 30S', '70S and 50S', '80S and 60S'], 'The 80S ribosome has 60S (large) and 40S (small) subunits; the 70S has 50S and 30S. Svedberg units do not add arithmetically.');
mc(3, 'cilia and flagella', 'Both cilia and flagella of eukaryotes emerge from', 'basal bodies, which are centriole-like structures', ['nucleolar organisers', 'mesosomes', 'microbodies'], 'The basal body has the same cartwheel pattern as a centriole. It lies at the base of cilia and flagella.');
mc(3, 'centrosome', 'Each centriole is made of how many peripheral fibrils, and of what are they made?', 'Nine evenly spaced fibrils, each a triplet of tubulin microtubules', ['Nine fibrils, each a doublet of microtubules', 'Eleven fibrils, each a single microtubule', 'Nine fibrils, each made of actin'], 'A centriole has 9 + 0 organisation: nine peripheral triplets, no central tubules, connected to a central hub by radial spokes.', 'The axoneme is 9+2 with doublets; the centriole is 9+0 with triplets.');
mc(3, 'nucleus', 'The space between the two membranes of the nuclear envelope is the', 'perinuclear space', ['intermembrane space of mitochondria', 'lumen of the Golgi', 'stroma'], 'The nuclear envelope has two parallel membranes separated by the perinuclear space (about 10 to 50 nm). The outer membrane is often continuous with the ER.');
mc(3, 'nucleus', 'The nucleolus is', 'a spherical structure with no membrane, the site of active rRNA synthesis', ['a membrane-bound vesicle holding histones', 'a pore of the nuclear envelope', 'the site of ATP synthesis in the nucleus'], 'The nucleolus is a content of the nucleoplasm and is not membrane-bound. Cells making a lot of protein have larger and more numerous nucleoli.');
mc(3, 'chromosomes', 'The chromatin of the nucleus contains', 'DNA, histones, some non-histone proteins and RNA', ['DNA and carbohydrates only', 'RNA and lipids only', 'DNA and phospholipids'], 'Chromatin is a thread-like stained material of DNA, basic proteins (histones), some non-histone proteins and RNA.');
mc(3, 'membrane', 'In which one of the following is the role of the membrane in the fluid mosaic model correctly stated?', 'The quasi-fluid nature of the lipid allows lateral movement of proteins within the layer', ['Proteins form a continuous coat outside the bilayer', 'The lipids cannot move once the bilayer forms', 'The membrane is a rigid sandwich of protein-lipid-protein'], 'Singer and Nicolson (1972) proposed that proteins float in the bilayer, which is quasi-fluid. This lateral movement helps in functions such as cell growth, formation of the intercellular junctions, secretion, endocytosis and cell division.');
mc(3, 'membrane', 'Overton (about 1895) suggested that the plasma membrane is made of lipids because', 'lipid-soluble substances enter the cell faster than those that are not', ['proteins were found in the nuclear envelope', 'sugars moved through it by osmosis', 'ATP was used during uptake of ions'], 'Overton observed that the substances soluble in lipids pass the membrane more quickly. This suggested the presence of lipids in the membrane.');
mc(3, 'membrane', 'Which statement is correct about transport of water across the membrane?', 'Water moves by osmosis, a diffusion from higher to lower water potential', ['Water moves only by active transport using ATP', 'Water can only cross by a specific carrier that needs ATP', 'Water cannot cross the plasma membrane'], 'Diffusion of water across a selectively permeable membrane is osmosis.');
mc(3, 'microbodies', 'Microbodies are', 'membrane-bound minute vesicles containing various enzymes, present in plant and animal cells', ['a stack of thylakoids in plastids', 'ribosomes bound to ER', 'organelles with 9+2 microtubules'], 'Microbodies (such as peroxisomes) are small single-membrane vesicles with different enzymes.');
mc(3, 'cytoskeleton', 'The cytoskeleton is a network of', 'microtubules, microfilaments and intermediate filaments', ['mitochondria and plastids', 'ER and Golgi', 'ribosomes and polysomes'], 'The cytoskeleton gives mechanical support, motility and maintains the shape of the cell. It comprises proteinaceous filamentous structures.');
asr(3, 'prokaryotic cell', 'A bacterial cell can have more than one type of ribosome-containing site in the cytoplasm but no ER.', 'Prokaryotes are generally without membrane-bound organelles.', 0, 'Prokaryotic cells lack the membrane-bound organelles such as ER, Golgi and mitochondria. Ribosomes are free or attached to the plasma membrane. R explains why there is no ER.');
asr(3, 'lysosomes', 'Lysosomal enzymes work best in an acidic medium.', 'Lysosomes maintain an acidic interior.', 0, 'The enzymes are optimally active at acidic pH, which the lysosome maintains. R explains A.');
asr(3, 'plastids', 'Ripe tomato fruit are red.', 'Chromoplasts of tomato fruit contain carotenoid pigments.', 0, 'Chromoplasts contain fat-soluble carotenoids that give red, yellow or orange colours. R explains A.');
asr(3, 'mitochondria', 'Mitochondria are called semi-autonomous organelles.', 'They have their own DNA and ribosomes, and divide by fission.', 0, 'They can make some of their own proteins and divide by themselves but still depend on the nucleus for many proteins. R explains A.');
asr(3, 'nucleus', 'Nucleoli are larger in cells that actively synthesise proteins.', 'The nucleolus is the site of ribosomal RNA synthesis.', 0, 'Many ribosomes are needed for active protein synthesis, which requires more rRNA; hence bigger nucleoli. R explains A.');
stm(3, 'cell wall', 'The middle lamella is made mainly of calcium pectate.', 'It holds the neighbouring plant cells together.', 0, 'Both are correct: the middle lamella is a layer of calcium pectate that glues adjacent cells.');
stm(3, 'ribosomes', 'Ribosomes are surrounded by a membrane in eukaryotes.', 'Ribosomes are composed of RNA and proteins.', 3, 'Ribosomes are not membrane-bound in any cell, so Statement I is incorrect. They are made of rRNA and proteins, so Statement II is correct.');
stm(3, 'ER', 'Rough ER has ribosomes on its cytoplasmic surface.', 'Smooth ER is the major site for protein synthesis for secretion.', 2, 'Statement I is correct. Statement II is wrong: SER makes lipids and steroids; protein synthesis for secretion occurs at RER.');
stm(3, 'vacuole', 'Plant vacuoles are bounded by tonoplast.', 'Contractile vacuoles of Amoeba excrete excess water.', 0, 'Both are correct statements.');
hm(3, 'double membrane', 'Consider these organelles. (1) Mitochondria (2) Golgi complex (3) Nucleus (4) Chloroplast. How many are bounded by two membranes?', 'Three', ['Two', 'One', 'All four'], 'Mitochondria, nucleus and chloroplast are double-membrane bound. The Golgi complex is single-membrane.', 'Count the nuclear envelope as two membranes.');
match(3, 'cell inclusions', 'xm1', 'Organelle and the process it is mainly associated with', ['A. Golgi complex', 'B. Mitochondrion', 'C. Smooth ER', 'D. Lysosome'], ['p. Packaging and glycosylation', 'q. ATP production', 'r. Lipid synthesis', 's. Intracellular digestion'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Golgi packages and modifies; mitochondria produce ATP; SER makes lipids; lysosomes digest.');
match(3, 'plastids', 'xm2', 'Plastid and stored substance or pigment', ['A. Amyloplast', 'B. Elaioplast', 'C. Aleuroplast', 'D. Chromoplast'], ['p. Starch', 'q. Oils and fats', 'r. Proteins', 's. Carotenoids'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Amylo = starch; elaio = oil; aleuro = protein; chromoplasts store carotenoid pigments.');
match(3, 'prokaryotic cell', 'xm3', 'Bacterial structure and role', ['A. Mesosome', 'B. Plasmid', 'C. Pili', 'D. Flagellum'], ['p. Antibiotic resistance genes', 'q. Increases surface area and helps DNA replication', 'r. Motility', 's. Tubular protein structure for attachment'], 'A-q, B-p, C-s, D-r', ['A-p, B-q, C-s, D-r', 'A-q, B-p, C-r, D-s', 'A-s, B-p, C-q, D-r'], 'Mesosome: infoldings that help in DNA replication and increase surface. Plasmid: extra-chromosomal DNA with resistance. Pili: tubular structure. Flagellum: motility.');

// ---- Level 4
mc(4, 'cell size', 'Arrange in order of increasing size: Mycoplasma, human RBC, a typical bacterium, ostrich egg', 'Mycoplasma < typical bacterium < human RBC < ostrich egg', ['Mycoplasma < human RBC < typical bacterium < ostrich egg', 'Typical bacterium < Mycoplasma < human RBC < ostrich egg', 'Mycoplasma < typical bacterium < ostrich egg < human RBC'], 'Mycoplasma is about 0.3 micrometre, bacteria 3 to 5 micrometre, human RBC about 7 micrometre, the ostrich egg is the largest isolated single cell.', 'Remember the numbers: 0.3, 3-5, 7.');
mc(4, 'membrane', 'Which of the following correctly states the composition of the human erythrocyte membrane?', 'About 52 per cent protein and 40 per cent lipid', ['About 40 per cent protein and 52 per cent lipid', 'About 80 per cent protein and 10 per cent lipid', 'About 70 per cent lipid and 20 per cent protein'], 'In human RBC the membrane has about 52% protein and 40% lipid (the rest carbohydrate). Ratio of protein to lipid varies with cell type: in myelin sheath of nerve cells, lipid is higher.', 'It is protein-rich in RBC.');
mc(4, 'membrane', 'A molecule needs a carrier protein, moves from a higher to a lower concentration, and needs no ATP. This is', 'facilitated diffusion', ['active transport', 'simple diffusion through the bilayer', 'endocytosis'], 'Facilitated diffusion uses a carrier but follows the gradient and needs no ATP. Active transport goes against the gradient and uses ATP.');
mc(4, 'membrane', 'The sodium-potassium pump is an example of', 'active transport against a concentration gradient using ATP', ['facilitated diffusion down a gradient', 'osmosis', 'simple diffusion'], 'Active transport (e.g. Na+/K+ pump) uses energy from ATP to move ions against the gradient.');
mc(4, 'endomembrane', 'Mitochondria, chloroplasts and peroxisomes are NOT considered part of the endomembrane system because', 'their functions are not coordinated with those of the ER, Golgi, lysosomes and vacuoles', ['they have a single membrane', 'they lack proteins', 'they are present only in prokaryotes'], 'NCERT says that the endomembrane system includes ER, Golgi, lysosomes and vacuoles because their functions are coordinated. Mitochondria, chloroplasts and peroxisomes are not coordinated with them.', 'Not because of double membrane, but because of non-coordinated function.');
mc(4, 'endomembrane', 'A protein made on the RER and finally put into a lysosome travels by the route', 'RER to Golgi cis face, Golgi trans face, lysosome', ['RER to lysosome directly, then Golgi', 'Golgi trans face to RER to lysosome', 'RER to mitochondria to lysosome'], 'Proteins made at the RER move in vesicles to the cis face of the Golgi, are modified, and are packaged at the trans face into lysosomes.');
mc(4, 'Golgi', 'Which of these is a function of the Golgi complex NOT performed by the ER?', 'Formation of glycoproteins and glycolipids', ['Synthesis of steroids', 'Synthesis of proteins by ribosomes', 'Formation of lipids'], 'The Golgi is the major site of formation of glycoproteins and glycolipids.');
mc(4, 'cell wall', 'Which structure connects the cytoplasm of two neighbouring plant cells, passing through the cell walls and middle lamella?', 'Plasmodesmata', ['Gap junctions', 'Pili', 'Pits of the nuclear envelope'], 'Plasmodesmata are cytoplasmic bridges (lined with plasma membrane) that run through the walls and middle lamella of neighbouring plant cells.');
mc(4, 'mitochondria', 'A mitochondrion has a length of about', '1.0 to 4.1 micrometre with a diameter of 0.2 to 1.0 micrometre', ['10 to 40 micrometre with diameter 2 to 10 micrometre', '0.01 to 0.04 micrometre in length', '5 to 10 micrometre in length and 2 to 4 micrometre wide'], 'NCERT gives the diameter of mitochondria as 0.2 to 1.0 micrometre (average 0.5) and length 1.0 to 4.1 micrometre. The chloroplast (5 to 10 by 2 to 4 micrometre) is bigger.', 'Do not mix with chloroplast size.');
mc(4, 'plastids', 'A chloroplast measures about', '5 to 10 micrometre in length and 2 to 4 micrometre in width', ['1 to 4 micrometre in length and 0.2 to 1 micrometre in width', '50 to 100 micrometre in length', '0.3 micrometre in length'], 'The chloroplast is typically lens-shaped, oval, spherical, discoid or even ribbon-like, 5 to 10 micrometre long and 2 to 4 micrometre wide.');
mc(4, 'plastids', 'Thylakoids of the chloroplast are arranged', 'in stacks called grana, with stroma lamellae connecting different grana', ['in a single long coil without stacks', 'only in the stroma lamellae', 'on the outer membrane'], 'Flattened membranous sacs (thylakoids) are organised into grana, connected by flat membranous tubules called stroma lamellae. Chlorophyll is in the thylakoid membranes.');
mc(4, 'cilia and flagella', 'In a cross section of a cilium the number of central microtubules, peripheral doublets and radial spokes are respectively', '2, 9 and 9', ['9, 2 and 9', '2, 9 and 18', '9, 9 and 2'], 'The axoneme has 9 peripheral doublets and 2 central single tubules (9+2), and the central sheath is joined to one tubule of each doublet by a radial spoke: 9 spokes.', 'It is 9+2, not 9+0.');
mc(4, 'centrosome', 'The centriole differs from the axoneme of a cilium in that the centriole has', 'nine peripheral triplets and no central tubules', ['nine peripheral doublets and two central tubules', 'two central triplets and nine singlets', 'nine peripheral triplets and two central tubules'], 'A centriole is 9+0 with triplets. A cilium axoneme is 9+2 with doublets.');
mc(4, 'chromosomes', 'A chromosome has a satellite. This is', 'a small segment beyond a secondary constriction at one end', ['the centromere', 'a kinetochore disc', 'a chiasma'], 'The secondary constriction at a constant location gives the satellite, which is the part of the chromosome beyond the constriction. Not all chromosomes have one.');
mc(4, 'nucleus', 'Which statement is NOT correct about the nuclear envelope?', 'The inner membrane carries ribosomes and is continuous with the ER', ['Nuclear pores are formed by fusion of the two membranes', 'The outer membrane is often continuous with the ER', 'Nuclear pores allow passage of RNA and proteins'], 'It is the outer membrane that often bears ribosomes and is continuous with the ER.', 'Outer, not inner.');
mc(4, 'prokaryotic cell', 'In cyanobacteria, the photosynthetic pigments are found in', 'membranous extensions of the cytoplasm called chromatophores', ['chloroplasts with grana', 'mitochondria', 'the nucleoid region'], 'Cyanobacteria have no chloroplasts. Their pigments lie in chromatophores, membranous extensions into the cytoplasm.');
mc(4, 'prokaryotic cell', 'Gas vacuoles are found in', 'blue-green, purple and green photosynthetic bacteria', ['all eukaryotic cells', 'only in fungi', 'only in plant guard cells'], 'Gas vacuoles are among the inclusion bodies of some photosynthetic bacteria. Phosphate granules, cyanophycean granules and glycogen granules are other inclusions. These are not bound by a membrane.');
mc(4, 'membrane', 'Which statement correctly distinguishes integral from peripheral proteins?', 'Integral proteins are partially or totally buried in the membrane; peripheral proteins lie on its surface', ['Integral proteins lie on the surface, peripheral are buried', 'Both are completely buried', 'Both are dissolved in the aqueous phase only'], 'Peripheral proteins lie on the surface of the membrane while integral proteins are partially or totally buried in it.');
mc(4, 'cell theory', 'Which statement about Rudolf Virchow is correct?', 'He explained that new cells arise from pre-existing cells', ['He first proposed that all plants are made of cells', 'He discovered the nucleus', 'He described the Golgi complex'], 'Virchow (1855) first explained that cells divide and new cells arise from pre-existing cells (omnis cellula-e cellula), modifying the cell theory.');
mc(4, 'ribosomes', 'In which of the following places will 70S ribosomes NOT be found?', 'The cytoplasm of a yeast cell', ['The chloroplast stroma', 'The mitochondrial matrix', 'The cytoplasm of a bacterium'], 'Eukaryotic cytoplasm has 80S ribosomes; chloroplasts, mitochondria and bacteria have 70S.');
mc(4, 'cell envelope', 'The cell envelope of a bacterial cell is a tightly bound three-layered structure. These layers are', 'the glycocalyx, the cell wall and the plasma membrane', ['the capsule, the nucleoid and the plasmid', 'the mesosome, the plasma membrane and the ribosomes', 'the middle lamella, the primary wall and the secondary wall'], 'Despite differences in their structure and function, the three layers act together as one protective unit, according to NCERT.');
asr(4, 'plastids', 'The chloroplast and mitochondria can both be classified as semi-autonomous organelles.', 'Both have circular DNA and 80S ribosomes.', 2, 'Both have DNA and ribosomes, so A is true. But their ribosomes are 70S, so R is false.', '70S, not 80S.');
asr(4, 'ER', 'Cells that secrete large amounts of proteins have abundant RER.', 'Proteins synthesised on the RER can enter the secretory pathway.', 0, 'RER ribosomes make proteins that enter the lumen and move to the Golgi for secretion. R explains A.');
asr(4, 'membrane', 'The plasma membrane is selectively permeable.', 'Water-soluble polar molecules cannot cross the lipid bilayer without membrane proteins.', 0, 'The bilayer is hydrophobic in its core, so polar molecules need carrier proteins. This is why only certain molecules cross; R explains A.');
asr(4, 'centrosome', 'Centrioles are absent in higher plant cells.', 'Higher plant cells do not divide.', 2, 'A is true: higher plant cells lack centrioles and form the spindle without them. R is false: they divide by mitosis.', 'Absence of centrioles does not mean no division.');
stm(4, 'nucleus', 'The outer membrane of the nuclear envelope can bear ribosomes.', 'The perinuclear space is between the two membranes of the envelope.', 0, 'Both are correct.');
stm(4, 'mitochondria', 'The inner mitochondrial membrane forms folds called cristae.', 'The cristae decrease the surface area for enzymes of ATP synthesis.', 2, 'Statement I is correct. Statement II is wrong: cristae increase the surface area.');
stm(4, 'ribosomes', 'The "S" in 70S stands for Svedberg unit, a measure of sedimentation rate.', 'The sedimentation coefficient is a direct measure of size and so 50S and 30S subunits add up to 80S.', 2, 'Statement I is correct. Statement II is wrong: S depends on size and shape, not simply additive, and 50S + 30S form 70S.');
stm(4, 'cilia and flagella', 'The eukaryotic flagellum is covered by plasma membrane.', 'The bacterial flagellum is also covered by plasma membrane.', 2, 'A eukaryotic cilium or flagellum is covered by plasma membrane (Statement I correct). The bacterial flagellum is not covered by a membrane sheath, it is a protein filament (Statement II incorrect).');
hm(4, 'plastids', 'Consider these statements. (1) Chloroplast has a double membrane. (2) Stroma lamellae connect grana. (3) Chloroplast DNA is circular. (4) Chloroplast ribosomes are 80S. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong because they are 70S.', '70S for chloroplast ribosomes.');
hm(4, 'membrane', 'Consider these statements. (1) Phospholipids have a hydrophilic head and hydrophobic tails. (2) Proteins of the plasma membrane can move laterally. (3) Active transport needs ATP. (4) Simple diffusion of polar molecules across the lipid bilayer is fast. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(1), (2) and (3) are correct. (4) is wrong: polar molecules cannot easily cross the hydrophobic core; they need carrier proteins.');
match(4, 'cell structures', 'xm4', 'Structure and number of membranes or feature', ['A. Mitochondrion', 'B. Ribosome', 'C. Golgi complex', 'D. Nucleus'], ['p. No membrane', 'q. Single membrane', 'r. Double membrane with pores', 's. Double membrane with cristae'], 'A-s, B-p, C-q, D-r', ['A-r, B-p, C-q, D-s', 'A-s, B-q, C-p, D-r', 'A-p, B-s, C-q, D-r'], 'Mitochondrion: double membrane, inner one folded into cristae. Ribosome: no membrane. Golgi: single. Nucleus: double-membrane envelope with pores.');
match(4, 'scientists', 'xm5', 'Scientist and contribution', ['A. Robert Hooke', 'B. Robert Brown', 'C. Singer and Nicolson', 'D. Rudolf Virchow'], ['p. Fluid mosaic model', 'q. Cells arise from pre-existing cells', 'r. Discovery of nucleus', 's. Observed cells in cork'], 'A-s, B-r, C-p, D-q', ['A-r, B-s, C-p, D-q', 'A-s, B-r, C-q, D-p', 'A-p, B-r, C-s, D-q'], 'Hooke: cork cells (1665). Brown: nucleus. Singer and Nicolson: fluid mosaic model (1972). Virchow: omnis cellula e cellula.');
match(4, 'chromosomes', 'xm6', 'Chromosome type and centromere position', ['A. Metacentric', 'B. Sub-metacentric', 'C. Acrocentric', 'D. Telocentric'], ['p. Terminal', 'q. Middle, with equal arms', 'r. Near the end, one very short arm', 's. Slightly away from the middle, with one arm slightly shorter'], 'A-q, B-s, C-r, D-p', ['A-s, B-q, C-r, D-p', 'A-q, B-s, C-p, D-r', 'A-r, B-s, C-q, D-p'], 'Metacentric: middle. Sub-metacentric: slightly off the middle. Acrocentric: very near the end. Telocentric: at the end.');
match(4, 'ER and Golgi', 'xm7', 'Structure and feature', ['A. Rough ER', 'B. Smooth ER', 'C. Cis face of Golgi', 'D. Trans face of Golgi'], ['p. Lipid and steroid synthesis', 'q. Ribosomes on the cytoplasmic surface', 'r. Receives vesicles from ER', 's. Gives off vesicles after modification'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'RER has ribosomes; SER makes lipids and steroids; the cis face is the receiving face; the trans face is the maturing face from which vesicles leave.');
pass('xp1', 'Passage: a membrane experiment', 'A student prepares a bag from a thin lipid bilayer containing no proteins and places it in water with three solutes: oxygen, glucose and sodium ions. After some time she finds that oxygen crosses easily. She then adds carrier proteins specific for glucose to the bilayer and finds that glucose now crosses down its gradient, but sodium ions still do not cross.');
pq('xp1', 3, 'membrane', 'Oxygen crosses the pure bilayer easily because', 'it is a small non-polar molecule that dissolves in the lipid', ['it is carried by a specific protein', 'it uses ATP', 'the bilayer has pores'], 'Non-polar molecules and small gases pass directly by simple diffusion through the hydrophobic core.');
pq('xp1', 4, 'membrane', 'When carriers are added, glucose crosses by', 'facilitated diffusion', ['active transport', 'osmosis', 'simple diffusion'], 'Carrier proteins help the polar glucose across down its gradient with no ATP: facilitated diffusion.');
pq('xp1', 4, 'membrane', 'To make the sodium ions move against their gradient, the student must add', 'a pump protein and a source of ATP', ['more lipids only', 'more water', 'only more carrier proteins for glucose'], 'Movement against a gradient is active transport and needs a pump protein plus energy from ATP.');
pass('xp2', 'Passage: an electron micrograph of a cilium', 'An electron micrograph shows the cross section of a eukaryotic cilium. The outer boundary is a single membrane. Inside there are nine pairs of microtubules arranged in a ring and two single microtubules at the centre. Thin bridges join each peripheral pair to a sheath around the central tubules.');
pq('xp2', 3, 'cilia and flagella', 'The arrangement seen in this section is called', '9+2', ['9+0', '9+3', '2+9 with triplets'], 'Nine peripheral doublets and two central singlets form the 9+2 array.');
pq('xp2', 4, 'cilia and flagella', 'The thin bridges joining the peripheral pairs to the central sheath are', 'radial spokes, nine in number', ['radial spokes, two in number', 'linkers, eighteen in number', 'hooks, nine in number'], 'Each peripheral doublet is joined to the central sheath by a radial spoke: nine spokes. The linkers are the connections between the adjacent peripheral doublets.');
pq('xp2', 4, 'cilia and flagella', 'The structure at the base of this cilium from which it grows is a', 'basal body, with the same structure as a centriole (9+0)', ['mesosome, with 9+2 structure', 'nucleolus, with 9+0 structure', 'chromoplast, with 9+2 structure'], 'The basal body has nine peripheral triplets and no central tubules, like a centriole.');
pass('xp3', 'Passage: a cell fractionation experiment', 'A tissue is homogenised and spun at increasing speeds to separate the organelles. One fraction contains structures with a double membrane. The inner membrane is folded, and the matrix contains circular DNA and ribosomes that sediment at 70S. A second fraction contains flattened single-membrane sacs stacked in a pile that receive vesicles at one face and release them at the other.');
pq('xp3', 3, 'mitochondria', 'The first fraction mainly contains', 'mitochondria', ['Golgi complexes', 'lysosomes', 'nucleoli'], 'A double membrane with folded inner membrane (cristae), circular DNA and 70S ribosomes: mitochondria.');
pq('xp3', 4, 'Golgi', 'The second fraction mainly contains', 'Golgi complexes', ['rough ER', 'chloroplasts', 'mesosomes'], 'Flattened stacked cisternae with cis and trans faces: Golgi.');
pq('xp3', 4, 'ribosomes', 'The ribosomes in the first fraction', 'resemble those of bacteria and are made of 50S and 30S subunits', ['resemble those of the cell cytoplasm, 80S', 'are 60S in size', 'are absent'], 'Organelle ribosomes of mitochondria are 70S (50S + 30S), like those of bacteria.');

// ---- Level 5
mc(5, 'prokaryotic cell', 'Which one of the following correctly pairs a bacterial feature with its function?', 'Slime layer : a loose sheath of glycocalyx outside the cell wall', ['Nucleoid : synthesis of proteins', 'Plasmid : essential for cell division', 'Pili : synthesis of ATP'], 'The glycocalyx is a loose sheath (slime layer) or a thick tough layer (capsule). The nucleoid holds the genome; plasmids are not essential; pili are for attachment.', 'Plasmids are optional.');
mc(5, 'membrane', 'Which observation best supports the "fluid" part of the fluid mosaic model?', 'Membrane proteins can move laterally in the plane of the bilayer', ['Lipids never exchange places with each other', 'Proteins form a fixed layer on both sides of the bilayer', 'The membrane contains only proteins and carbohydrates'], 'The quasi-fluid nature of lipids lets proteins diffuse laterally, which helps in functions such as cell growth, intercellular junctions, secretion, endocytosis and cell division.');
mc(5, 'nucleus', 'A cell shows many large nucleoli. Which prediction is most justified?', 'It makes a large amount of protein and needs many ribosomes', ['It is in the M phase', 'It is dormant', 'It has no ribosomes'], 'The nucleolus is the site of ribosomal RNA synthesis; large and more numerous nucleoli are in cells making lots of protein.', 'Nucleoli are absent in the M phase.');
mc(5, 'chromosomes', 'In the interphase nucleus, the chromatin is', 'loosely packed, and the nucleoplasm contains nucleoli and chromatin', ['condensed into visible chromosomes', 'enclosed in a membrane inside the nucleoplasm', 'made of RNA only'], 'In interphase chromatin appears as thin, dispersed threads. Chromosomes become visible during cell division.');
mc(5, 'centrosome', 'A centrosome contains', 'two cylindrical centrioles at right angles to each other, surrounded by pericentriolar material', ['one centriole inside a nucleus', 'two centrioles parallel to each other', 'four centrioles side by side'], 'In NCERT the two centrioles of a centrosome lie perpendicular to each other, each surrounded by amorphous pericentriolar material. Centrioles form the basal body of cilia and flagella and spindle fibres.');
mc(5, 'double membrane', 'Which pair has both members with a single-membrane boundary?', 'Lysosome and vacuole', ['Nucleus and lysosome', 'Chloroplast and vacuole', 'Mitochondrion and Golgi complex'], 'Lysosomes, vacuoles, Golgi and ER are single-membrane. Nucleus, mitochondria and chloroplasts have two membranes.');
mc(5, 'lysosomes', 'Which of the following is correct about the lysosomal enzymes?', 'They are made on rough ER, modified, and packaged in the Golgi complex', ['They are made on smooth ER and packaged in mitochondria', 'They are made in the nucleolus', 'They are made on free ribosomes and stored in the vacuole'], 'As a protein made on the RER, a hydrolytic enzyme passes to the Golgi complex and is packaged in a lysosome.');
mc(5, 'cell wall', 'In a plant tissue of a woody plant, the cell wall of a mature cell is formed of the three layers in the order from outside to inside:', 'middle lamella, primary wall, secondary wall', ['secondary wall, primary wall, middle lamella', 'primary wall, middle lamella, secondary wall', 'middle lamella, secondary wall, primary wall'], 'The middle lamella is the outermost and common to neighbouring cells; the primary wall is next; the secondary wall is laid down inside it as the cell matures.');
mc(5, 'ribosomes', 'Polysomes (polyribosomes) are', 'several ribosomes attached to a single mRNA, translating it', ['ribosomes joined by membranes to the nucleus', 'ribosomes of 100S size', 'subunits stored in the nucleolus'], 'Ribosomes may attach to a single mRNA and form a chain, the polysome, which makes several copies of the protein at once.');
asr(5, 'ribosomes', 'In a eukaryotic cell the 40S and 60S subunits together make 80S, not 100S.', 'The S value depends on shape and size, not only on mass, so it is not additive.', 0, 'Svedberg units measure sedimentation rate, which is not simply additive. R explains A.');
asr(5, 'membrane', 'Cholesterol content affects fluidity of the membrane.', 'Cholesterol is a polar molecule found outside the membrane.', 2, 'A is true: cholesterol modulates fluidity. R is false: cholesterol is part of the membrane lipids, embedded in the bilayer.');
asr(5, 'mitochondria', 'The mitochondrial matrix can synthesise some of its own proteins.', 'The matrix has circular DNA, RNA and 70S ribosomes.', 0, 'With its own genome and translation machinery, a mitochondrion can make some proteins. R explains A.');
asr(5, 'vacuole', 'Plant cells can store ions inside the vacuole at a higher concentration than outside.', 'The tonoplast allows diffusion of ions along the gradient without any energy.', 2, 'A is true. R is false: accumulation against the gradient needs energy; the tonoplast facilitates the transport of ions against a concentration gradient.', 'Accumulation is active.');
stm(5, 'chloroplast', 'Chloroplast stroma contains enzymes for the synthesis of carbohydrates and proteins.', 'The grana are connected by the stroma lamellae.', 0, 'Both are correct. The stroma has enzymes for carbohydrate and protein synthesis, small circular DNA and 70S ribosomes. The grana are joined by stroma lamellae.');
stm(5, 'nucleus', 'The nucleolus is bounded by a double membrane.', 'The nucleolus is a site of rRNA synthesis.', 3, 'The nucleolus has no membrane (Statement I incorrect). It is a site for active rRNA synthesis (Statement II correct).');
hm(5, 'prokaryotic cell', 'Consider these statements. (1) All prokaryotes have a cell wall of the same chemical composition. (2) Mycoplasma has no cell wall. (3) Bacterial ribosomes are 70S. (4) Bacterial cells have no membrane-bound nucleus. How many are correct?', 'Only three', ['Only two', 'All four', 'Only one'], '(2), (3) and (4) are correct. Mycoplasmas are the smallest living cells and lack a cell wall. (1) is wrong: the composition varies, e.g. Gram positive and Gram negative.', 'Mycoplasma has no wall.');
match(5, 'cell parts', 'xm8', 'Structure and a number or size to remember', ['A. Mycoplasma', 'B. Human RBC', 'C. Mitochondrial diameter', 'D. Radial spokes of an axoneme'], ['p. 9', 'q. About 0.3 micrometre', 'r. About 7 micrometre', 's. 0.2 to 1.0 micrometre'], 'A-q, B-r, C-s, D-p', ['A-r, B-q, C-s, D-p', 'A-q, B-r, C-p, D-s', 'A-s, B-r, C-q, D-p'], 'Mycoplasma 0.3 micrometre; human RBC 7.0 micrometre diameter; mitochondria 0.2 to 1.0 micrometre diameter; nine radial spokes.');
match(5, 'cell envelope', 'xm9', 'Layer and nature', ['A. Capsule', 'B. Slime layer', 'C. Middle lamella', 'D. Secondary wall'], ['p. Thick, tough glycocalyx of bacteria', 'q. Loose sheath of bacteria', 'r. Calcium pectate that cements cells', 's. Layer formed inside the primary wall as the cell matures'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Capsule is thick glycocalyx; slime layer is loose; middle lamella is calcium pectate; secondary wall is deposited inside.');
match(4, 'ribosomes', 'xm10', 'Cell structure and ribosome type or size', ['A. Bacterial ribosome', 'B. Eukaryotic cytoplasmic ribosome', 'C. Large subunit of eukaryotic ribosome', 'D. Small subunit of bacterial ribosome'], ['p. 70S', 'q. 80S', 'r. 60S', 's. 30S'], 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], 'Prokaryotic ribosome: 70S (50S + 30S). Eukaryotic ribosome: 80S (60S + 40S).');

export default { topic: 'cell', groups, items, gens: [] };
